const rawHTMLBody = $json.textHtml || $json.html || '';
const threadID = $json.threadId;
const emailID = $json.id;
const emailDate = $json.date

const body = rawHTMLBody
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return {
  emailID,
  threadID,
  emailDate,
  body
}

return $input.all().map(raw => {
  const { status, acquirer, amount, category, 
          senderName, senderAccount, recipientName, 
          recipientAccount, merchantLocation, transactionType
        } = JSON.parse(raw.json.message.content);

  return {
    emailID: raw.json.emailID,
    transactionDate: raw.json.transactionDate,
    status,
    acquirer,
    amount,
    transactionType,
    category,
    senderName,
    senderAccount,
    recipientName,
    recipientAccount,
    merchantLocation,
  }
});
